// src/render/Texture.h
// Wraps one OpenGL 2D texture (RAII).
// For now the pictures are generated by code (no stb_image needed yet).
// Later, a loadFromFile() using stb_image can be added without changing anything else.
#pragma once
#include <functional>
#include <glm/glm.hpp>

class Texture {
public:
    // channels = 3 (RGB) or 4 (RGBA). pixels = w*h*channels bytes.
    Texture(int width, int height, int channels, const unsigned char* pixels);
    ~Texture();

    Texture(const Texture&) = delete;
    Texture& operator=(const Texture&) = delete;
    Texture(Texture&& other) noexcept;
    Texture& operator=(Texture&& other) noexcept;

    void bind(unsigned int unit = 0) const;
    void setNearest() const;     // no smoothing: keeps pixel-art / pixel-font text sharp

    // Build a texture by asking fn(x, y) for the colour (0..1) of every pixel.
    static Texture fromFunction(int w, int h, const std::function<glm::vec3(int, int)>& fn);

    // Procedural textures (all 128x128 and seamlessly tileable).
    static Texture createBrick();
    static Texture createConcrete();
    static Texture createWoodFloor();
    static Texture createGrass();
    static Texture createBlackboard();
    static Texture createChecker();

private:
    unsigned int m_id = 0;
};
